79	// ── Ergebnis-POD: bool + die Fehler-Liste (literal, fuer die Host-Ausgabe + Tests). ──
80	struct ProfileValidationResult {
81	    bool                     ok = true;
82	    std::vector<std::string> errors;   // je ungueltiger Eintrag eine klare Meldung
83	    std::vector<std::string> warnings; // nicht-fatale Hinweise (z.B. leere <value>-Liste = Registry-Expansion)
84	    std::size_t              axes_checked     = 0;
85	    std::size_t              values_checked   = 0;
86	    std::size_t              sweeps_checked   = 0;
87	    std::size_t              series_checked   = 0;
88	    std::size_t              datasets_checked = 0; // GO-5 Fork 1: geprueften <dataset>-Eintraege (0 = keine deklariert)
89	    std::size_t workloads_checked = 0; // M-CE-12: gepruefte <workloads>-ids (0 = keine / Pruefung uebersprungen)
90	    std::size_t categories_checked =
91	        0; // INC-3 Familie A: gepruefte <measurement_categories>-Namen (0 = keine deklariert)
92	};
93	
94	// ── GO-5 Fork 6 (Thesis §sec:fairness): die zwei erlaubten Fairness-Modi einer <sota_series>. ──
95	inline constexpr char const* kFairnessModes[] = {"common_denominator", "native"};
96	
97	// ── GO-5 Fork 1: die im Repo existenten DatasetLoaderRegistry-loader_ids (Quelle: die Selbst-
98	//    Registrierungen in libs/common/measurement/dataset_loader/include/.../loaders/*.hpp —
99	//    string_corpus_loader.hpp + sosd_uint64_loader.hpp). Die Registry ist laufzeit-OFFEN (weitere
100	//    Loader registrierbar) → ein fremder loader ist WARNUNG, kein Fehler (s. Kopf-Doku (5)). ──
101	inline constexpr char const* kKnownDatasetLoaderIds[] = {"string_corpus", "sosd_uint64"};
102	
103	/// axis_registry_from_levels — formt die AxisLevel-Liste (z.B. build_all_axis_levels()) in eine AxisRegistry
104	/// (axis-Name → gueltige Werte). Das ist der READ-ONLY Brueckenkopf: build_all_axis_levels() reflektiert die
105	/// REALEN EnabledStrategies (reflect_names<…StaticAxisVariants*>), HIER nur als map umgehaengt — keine Wahl.
106	[[nodiscard]] inline ex::AxisRegistry axis_registry_from_levels(std::vector<ex::AxisLevel> const& levels) {
107	    ex::AxisRegistry reg;
108	    for (auto const& l : levels) reg[l.axis] = l.values; // axis → volle name()-Liste (EnabledStrategies)
109	    return reg;
110	}
111	
112	// ── Hilfs: gueltige Werte-Vorschau (max 12, sonst "… (+N)") fuer eine lesbare Fehlermeldung. ──
113	[[nodiscard]] inline std::string preview_values(std::vector<std::string> const& vals) {
114	    std::string       s;
115	    std::size_t const cap = (std::min<std::size_t>)(vals.size(), 12);
116	    for (std::size_t i = 0; i < cap; ++i) {
117	        if (i) s += ", ";
118	        s += vals[i];
119	    }
120	    if (vals.size() > cap) s += ", … (+" + std::to_string(vals.size() - cap) + ")";
121	    return s;
122	}
