42	struct ValidationReport {
43	    std::vector<ValidationIssue> issues;
44	    bool                         valid{false};
45	
46	    [[nodiscard]] bool has_errors() const noexcept {
47	        for (const auto& i : issues) {
48	            if (i.severity == ValidationIssue::Severity::Error) return true;
49	        }
50	        return false;
51	    }
