58	class MessreiheV32Validator {
59	public:
60	    [[nodiscard]] static ValidationReport validate_string(std::string_view xml) {
61	        ValidationReport report;
62	
63	        // Pflicht: XML-Header
64	        if (xml.find("<?xml") == std::string_view::npos) { add_error(report, "Missing <?xml declaration"); }
65	
66	        // Pflicht: <messreihe version="32"> Root-Element
67	        if (xml.find("<messreihe") == std::string_view::npos) {
68	            add_error(report, "Missing root element <messreihe>");
69	        } else if (xml.find("version=\"32\"") == std::string_view::npos) {
70	            add_error(report, "Root <messreihe> must have version=\"32\"");
71	        }
72	
73	        // Pflicht: <metadata> mit <mode>
74	        require_element(report, xml, "<metadata>", "metadata block");
75	        require_element(report, xml, "<name>", "metadata/name");
76	        require_element(report, xml, "<mode>", "metadata/mode");
77	        if (xml.find("<mode>defined</mode>") == std::string_view::npos &&
78	            xml.find("<mode>full</mode>") == std::string_view::npos &&
79	            xml.find("<mode>full_sampled</mode>") == std::string_view::npos) {
80	            add_error(report, "metadata/mode must be 'defined', 'full', or 'full_sampled'");
81	        }
82	
83	        // Pflicht: <execution_engines> mit GENAU 2 <engine>
84	        require_element(report, xml, "<execution_engines>", "execution_engines block");
85	        const auto engine_count = count_occurrences(xml, "<engine ");
86	        if (engine_count != 2) {
87	            add_error(report,
88	                      "execution_engines must contain exactly 2 <engine>, found " + std::to_string(engine_count));
89	        }
90	
91	        // Pflicht: mindestens 1 <tupel>
92	        const auto tupel_count = count_occurrences(xml, "<tupel ");
93	        if (tupel_count == 0) { add_error(report, "At least one <tupel> required"); }
94	        // Pro tupel: <workload>
95	        const auto workload_count = count_occurrences(xml, "<workload ");
96	        if (workload_count < tupel_count) {
97	            add_error(report, "Every <tupel> needs a <workload>, found " + std::to_string(workload_count) +
98	                                  " workloads for " + std::to_string(tupel_count) + " tupels");
99	        }
100	
101	        // Pflicht: <output> mit Pfaden
102	        require_element(report, xml, "<output>", "output block");
103	        require_element(report, xml, "<binary_path>", "output/binary_path");
104	        require_element(report, xml, "<csv_path>", "output/csv_path");
105	        require_element(report, xml, "<latex_path>", "output/latex_path");
106	
107	        // Optional: <axes_default_lookup enabled="...">
108	        if (xml.find("<axes_default_lookup") != std::string_view::npos &&
109	            xml.find("enabled=\"") == std::string_view::npos) {
110	            add_warning(report, "axes_default_lookup present but enabled-attribute missing");
111	        }
112	
113	        // Closing tag
114	        if (xml.find("</messreihe>") == std::string_view::npos) { add_error(report, "Missing closing </messreihe>"); }
115	
116	        report.valid = !report.has_errors();
117	        return report;
118	    }
