133	    // (messreihe_v32_parser.hpp::parse_messreihe_v32) gelieferten Struct-Felder. Additiv zum
134	    // DEPRECATED string-find-Pfad oben. Template (statisches Duck-Typing) statt hartem #include —
135	    // s. Header-Kommentar. `MessreiheV32Like` ist erwartungsgemaess das MessreiheV32-Struct.
136	    template <class MessreiheV32Like>
137	    [[nodiscard]] static ValidationReport validate_parsed(MessreiheV32Like const& m) {
138	        ValidationReport report;
139	
140	        // Pflicht: GENAU 2 <engine> (XSD ExecutionEnginesType minOccurs=maxOccurs=2)
141	        if (m.engines.size() != 2) {
142	            add_error(report,
143	                      "execution_engines must contain exactly 2 <engine>, parsed " + std::to_string(m.engines.size()));
144	        }
145	
146	        // Pflicht: mode aus {defined, full, full_sampled}
147	        if (m.metadata.mode != "defined" && m.metadata.mode != "full" && m.metadata.mode != "full_sampled") {
148	            add_error(report,
149	                      "metadata/mode must be 'defined', 'full', or 'full_sampled' (parsed: '" + m.metadata.mode + "')");
150	        }
151	
152	        // Pflicht: mindestens 1 <tupel>, jeder mit <workload>, op_type (falls gesetzt) gueltig
153	        if (m.tupel.empty()) { add_error(report, "At least one <tupel> required (parsed 0)"); }
154	        for (const auto& t : m.tupel) {
155	            if (!t.has_workload) { add_error(report, "tupel '" + t.id + "' missing <workload>"); }
156	            if (!t.op_type.empty() && !is_valid_op_type(t.op_type)) {
157	                add_error(report, "tupel '" + t.id + "' has invalid op_type '" + t.op_type + "' (expected OP-1..OP-6)");
158	            }
159	        }
160	
161	        // comparison_metrics MUSS gelesen worden sein (OutputType, xs:boolean)
162	        if (!m.output.has_comparison_metrics) {
163	            add_warning(report, "output/comparison_metrics not present (F15-Verdict/Ratios undefiniert)");
164	        }
165	
166	        report.valid = !report.has_errors();
167	        return report;
168	    }
