180	        report.issues.push_back({ValidationIssue::Severity::Warning, msg});
181	    }
182	    static void require_element(ValidationReport& report, std::string_view xml, std::string_view needle,
183	                                std::string_view human) {
184	        if (xml.find(needle) == std::string_view::npos) {
185	            add_error(report, "Missing " + std::string(human) + " (needle: " + std::string(needle) + ")");
186	        }
187	    }
188	    static std::size_t count_occurrences(std::string_view haystack, std::string_view needle) {
189	        if (needle.empty()) return 0;
190	        std::size_t count = 0;
191	        std::size_t pos   = 0;
192	        while ((pos = haystack.find(needle, pos)) != std::string_view::npos) {
193	            ++count;
194	            pos += needle.size();
195	        }
196	        return count;
197	    }
